    "description": "10月9日，A股有机硅概念板块继续走强，东岳硅材、晨光新材、新亚强涨停，硅宝科技、合盛硅业等多股跟涨。业内人士分析称，行业供需关系改善、产品价格回升及上市公司盈利修复预期，共同推动有机硅板块走高。除周期性供需改善外，新能源、电子电气及半导体等领域的应用拓展，也为有机硅产业链带来新的增长空间。（上证报）",
