    "description": "德国金融监管机构对大众汽车处以120 万欧元（折合 130 万美元）罚款，认定这家汽车制造商未能及时、合规地披露可能影响市场的重大信息。该监管机构简称 BaFin，于周五公布：大众汽车 2023 财年业绩预告大幅超出市场预期，对于这份预告所反映的经营情况，这家德国车企本应当面向金融市场发布临时即时公告（ad‑hoc 公告）。（新浪财经）",
