    "link": "http://www.news.cn/20261010/17500ba1981c438fa3f3925c1163d62f/c.html",
    "pub_date": "2026-10-10 08:57:17",
    "author": "王学涛,徐伟",
    "description": "新华社太原10月10日电（记者王学涛、徐伟）城墙是阅读一座古城的序。 十月的山西平遥，天高云淡。站在南门城墙上眺望，一城青砖灰瓦尽收眼底。南门为龟首，北门为龟尾，东西上下四门如四肢，南大街作脊梁，四大街、八小街、七十二条蚰蜒巷如龟背纹图——这座“龟城”，寄寓着古人盼其坚固长寿的愿望。 经过2800余年洗礼，2.25平方公里的古城内，300余处文物、近4000处传统建筑静静矗立。平遥古城是中国现存最完整的古城之一，也是中国汉民族城市在明清…",
    "content": "新华社太原10月10日电（记者王学涛、徐伟）城墙是阅读一座古城的序。 十月的山西平遥，天高云淡。站在南门城墙上眺望，一城青砖灰瓦尽收眼底。南门为龟首，北门为龟尾，东西上下四门如四肢，南大街作脊梁，四大街、八小街、七十二条蚰蜒巷如龟背纹图——这座“龟城”，寄寓着古人盼其坚固长寿的愿望。 经过2800余年洗礼，2.25平方公里的古城内，300余处文物、近4000处传统建筑静静矗立。平遥古城是中国现存最完整的古城之一，也是中国汉民族城市在明清时期的杰出范例，开创了中国以整座古城列入世界文化遗产名录的先河。 “真实而完整，…"
