    "description": "新华社巴拿马城10月9日电（记者许咏政 李佳旭）据美国地质调查局地震信息网消息，巴拿马上皮塔洛萨地区附近当地时间9日12时56分（北京时间10日1时56分）发生7.6级地震。巴拿马大学地球科学研究所将此次地震定级为7.2级。巴拿马首都巴拿马城震感明显。 巴拿马大学地球科学研究所称，强震后又记录到多次余震，其中一次震级达到6级。地震还造成部分地区建筑物受损，具体损失仍在统计中。 强震后，经记者多方核实，截至目前，驻巴拿马中资机构及当地华侨…",
    "content": "新华社巴拿马城10月9日电（记者许咏政 李佳旭）据美国地质调查局地震信息网消息，巴拿马上皮塔洛萨地区附近当地时间9日12时56分（北京时间10日1时56分）发生7.6级地震。巴拿马大学地球科学研究所将此次地震定级为7.2级。巴拿马首都巴拿马城震感明显。 巴拿马大学地球科学研究所称，强震后又记录到多次余震，其中一次震级达到6级。地震还造成部分地区建筑物受损，具体损失仍在统计中。 强震后，经记者多方核实，截至目前，驻巴拿马中资机构及当地华侨华人暂无人员伤亡报告。 据外媒报道，美国海啸预警系统当天在巴拿马地震后发出警报，…"
