    "content": "新华社巴拿马城10月9日电（记者许咏政 李佳旭）继强震之后，巴拿马9日又发生多次余震，其中一次震级达到6级。目前，当地有关部门正在评估地震造成的损失。 当日中午发生地震后，巴拿马大学地球科学研究所称已记录到多次余震，其中一次震级达到6级。地震还造成部分地区建筑物受损，具体损失仍在统计中。 据美国地质调查局地震信息网消息，巴拿马当地时间9日12时56分（北京时间10日1时56分），上皮塔洛萨地区附近发生7.6级地震，震中位于北纬7.60度、西经80.76度，震源深度10公里。巴拿马大学地球科学研究所测定的此次地震震级…"
