    "content": "新华社纽约10月9日电（记者刘亚南 徐静）美国白宫9日公布的信息显示，美总统特朗普7日签署备忘录，成立一个委员会，调查有关美国联邦储备委员会理事莉萨·库克涉嫌住房抵押贷款欺诈的指控，并就是否构成解除其职务的理由提出建议。 根据该备忘录，这一调查委员会由总统经济政策助理、美国平等就业机会委员会主席和政府道德准则办公室主任组成，将于11月5日在白宫举行闭门听证会，审议针对库克的证据和指控，库克本人须出席。 备忘录规定了调查流程及相关程序安排，要求委员会尽早向总统提交书面报告。 库克的代理律师在一份声明中表示，库克欢迎有…"
