    "description": "新华社圣地亚哥10月9日电（记者朱雨博）智利海军水文和海洋局海啸预警部门9日发布公告说，当天巴拿马地震可能引发海啸并影响智利复活节岛。 公告显示，海啸预计将于智利当地时间9日22时41分抵达复活节岛，其影响可能长达数小时。 据美国地质调查局地震信息网消息，巴拿马上皮塔洛萨地区附近格林尼治时间9日17时56分（北京时间10日1时56分），发生7.6级地震，震中位于北纬7.60度、西经80.76度，震源深度10公里。大约半小时后，巴拿马发生…",
    "content": "新华社圣地亚哥10月9日电（记者朱雨博）智利海军水文和海洋局海啸预警部门9日发布公告说，当天巴拿马地震可能引发海啸并影响智利复活节岛。 公告显示，海啸预计将于智利当地时间9日22时41分抵达复活节岛，其影响可能长达数小时。 据美国地质调查局地震信息网消息，巴拿马上皮塔洛萨地区附近格林尼治时间9日17时56分（北京时间10日1时56分），发生7.6级地震，震中位于北纬7.60度、西经80.76度，震源深度10公里。大约半小时后，巴拿马发生两次5级以上地震。"
