    "description": "新华社阿布扎比10月9日电（记者温新年）阿联酋总检察长沙姆西9日说，对迪拜航空FZ1073航班事件的调查显示，涉事副驾驶企图驾驶飞机撞击以色列特拉维夫本-古里安国际机场航站楼，实施自杀式恐怖袭击，造成尽可能多的人员伤亡。 沙姆西当天发表声明说，涉事副驾驶是一名29岁的阿曼籍男子。他事先制定了袭击计划，并利用此前两次飞往特拉维夫的航班熟悉飞行路线和机场情况，随后于9月30日第三次执行该航线任务时试图实施袭击。 调查显示，嫌疑人2017年在…",
    "content": "新华社阿布扎比10月9日电（记者温新年）阿联酋总检察长沙姆西9日说，对迪拜航空FZ1073航班事件的调查显示，涉事副驾驶企图驾驶飞机撞击以色列特拉维夫本-古里安国际机场航站楼，实施自杀式恐怖袭击，造成尽可能多的人员伤亡。 沙姆西当天发表声明说，涉事副驾驶是一名29岁的阿曼籍男子。他事先制定了袭击计划，并利用此前两次飞往特拉维夫的航班熟悉飞行路线和机场情况，随后于9月30日第三次执行该航线任务时试图实施袭击。 调查显示，嫌疑人2017年在澳大利亚留学期间开始接受极端主义思想，并受美国“9·11”恐怖袭击事件影响，萌生…"
