    "content": "新华社北京10月9日电 俄罗斯官方8日说，已向世界卫生组织通报俄罗斯伊尔库茨克西伯利亚与远东防鼠疫研究所一名工作人员患病死亡的相关情况，并未出现第二例病例；当前防疫形势平稳，已解除相关预防性措施。 据俄方通报，该研究所一名28岁女性工作人员2日因“不明原因肺炎”死亡。伊尔库茨克州州长伊戈尔·科布泽夫8日在俄社交媒体平台上说，目前对所有与患者有接触人员的医学观察都已结束，“未发现与传染病有关的健康问题”，死亡患者感染的是“社区获得性肺炎”。 俄联邦消费者权益保护和公益监督局8日发布通告，否认存在第二例病例。该机构表示…"
