    "content": "新华社北京10月9日电 题：苏州工业园区何以持续领跑 经济参考报记者梁智勇、吴蔚、杨绍功 培育科技型中小企业4500多家、国家高新技术企业3200余家、国家级专精特新“小巨人”企业220家……新质生产力在苏州工业园区奔涌成潮，这个园区在国家级经开区综合考评中已连续多年蝉联榜首。 稳居前列 “新”意盎然 稳居前列，苏州工业园区靠的是全面均衡的综合实力。 看经济总量：2025年实现地区生产总值4163.1亿元，同比增长5.5%，今年上半年同比增长6.2%，稳居全国经开区第一梯队。 看开放能级：2025年进出口总额首次突…"
