    "content": "新华社北京10月9日电（记者岳冉冉、李春宇）2026年世界乒乓球职业大联盟（WTT）中国大满贯赛9日继续进行，中国选手周启豪闯入男单四强，王曼昱、陈幸同晋级女单四强；韩国组合林鍾勋/申裕斌获得混双冠军。 作为国乒男队唯一进入八强的选手，周启豪在男单四分之一决赛中对阵韩国名将张禹珍。最终周启豪以4:2逆转获胜，首次闯入四强。 “跟张禹珍打还是要做好变化和调整，因为对手的技战术特点比较突出，他一开始打得我特别难受，好多球都被他限制住了，整个局面自己处于下风。”周启豪说，“不过在落后的情况下，我也是一分分拼，把比分咬回来…"
