    "content": "新华社北京10月9日电（记者郑直 刘芳洲）2026中国网球公开赛渐近尾声却更入佳境。9日，刚满24岁的郑钦文再度闯入女单四强，将在半决赛对阵比利时名将梅尔滕斯；张帅则携手捷克选手西尼亚科娃首度闯入中网女双四强。 当日的女单四分之一决赛，郑钦文迎战6号种子、乌克兰选手斯维托丽娜，这是两人首次在正式比赛中交手。首盘郑钦文三度破发，耗时45分钟以6:3拿下，次盘她的状态略有起伏一度落后，不过双方“抢七”局战至6:6后她连得两分终结比赛。这也是本届中网她首次直落两盘击败对手。 比赛结束时，郑钦文躺倒在地，享受全场欢呼。四强…"
