    "content": "新华社开罗10月9日电（记者俞启涵）喀土穆消息：苏丹青尼罗河州政府9日发表声明说，该州一处流离失所者营地遭无人机袭击，已造成30人死亡，另有数十人受伤。 声明说，袭击发生在青尼罗河州首府达马津以东约50公里处。该州政府谴责准军事组织快速支援部队发动此次袭击，称其严重违反国际人道主义法，呼吁国际社会和人权组织展开调查并追究相关人员责任。 一名目击者告诉新华社记者，一架无人机9日清晨向该流离失所者营地投掷了多枚炸弹。遇难者大多数是妇女和儿童。 快速支援部队尚未就此事表态。 2023年4月15日，苏丹军方与快速支援部队在…"
