    "author": "白瀛",
    "description": "新华社济南10月9日电（记者白瀛、邵琨）第35届中国电视剧“飞天奖”、第29届全国电视文艺“星光奖”获奖结果9日晚在山东烟台举行的颁奖典礼上揭晓。电视纪录片《文化的力量——习近平文化思想在浙江的溯源与实践》等14部作品获“星光奖”，《西北岁月》《生万物》等16部作品获“飞天奖”优秀电视剧奖。 获得“飞天奖”优秀电视剧奖的作品还有：《山花烂漫时》《我是刑警》《日光之城》《海天雄鹰》《春风化雨》《我的阿勒泰》《南来北往》《小巷人家》《国色芳…",
    "content": "新华社济南10月9日电（记者白瀛、邵琨）第35届中国电视剧“飞天奖”、第29届全国电视文艺“星光奖”获奖结果9日晚在山东烟台举行的颁奖典礼上揭晓。电视纪录片《文化的力量——习近平文化思想在浙江的溯源与实践》等14部作品获“星光奖”，《西北岁月》《生万物》等16部作品获“飞天奖”优秀电视剧奖。 获得“飞天奖”优秀电视剧奖的作品还有：《山花烂漫时》《我是刑警》《日光之城》《海天雄鹰》《春风化雨》《我的阿勒泰》《南来北往》《小巷人家》《国色芳华》《沉默的荣耀》《归队》《浴血荣光》《反人类暴行》《我们的河山》。 “飞天奖”…"
