    "author": "李松",
    "description": "新华社重庆10月9日电 重庆市纪委监委9日通报，经重庆市委批准，重庆市纪委监委对重庆商业投资集团有限公司原党委书记、董事长范光明严重违纪违法问题进行了立案审查调查。 经查，范光明丧失理想信念，背弃初心使命，对党不忠诚不老实，对抗组织审查，搞迷信活动；违背组织原则，不按规定报告个人有关事项，在职工录用、工作调动中为他人谋取利益并收受财物；廉洁底线失守，违规收受礼金、消费卡，通过民间借贷获取大额回报，违规从事营利活动；腐化堕落，利用职务便利…",
    "content": "新华社重庆10月9日电 重庆市纪委监委9日通报，经重庆市委批准，重庆市纪委监委对重庆商业投资集团有限公司原党委书记、董事长范光明严重违纪违法问题进行了立案审查调查。 经查，范光明丧失理想信念，背弃初心使命，对党不忠诚不老实，对抗组织审查，搞迷信活动；违背组织原则，不按规定报告个人有关事项，在职工录用、工作调动中为他人谋取利益并收受财物；廉洁底线失守，违规收受礼金、消费卡，通过民间借贷获取大额回报，违规从事营利活动；腐化堕落，利用职务便利为他人在工程承揽、资质审批、职工录用等方面谋利，并非法收受巨额财物。 范光明严重…"
