    "content": "新华社北京10月9日电（记者邢拓、白瀛）由北京人民艺术剧院与北京市东城区联合主办的2026北京人艺国际戏剧邀请展10月9日晚在京开幕。即日起至11月15日，北京人艺四个剧场将上演来自12个国家和地区的50场精品演出，为观众奉上多元荟萃、融通中外的戏剧盛宴。 本届邀请展设置国际特邀、海峡两岸邀约、高校青年戏剧孵化3大单元，其中8部剧目为全国首演、12部为北京首演。国际特邀单元将呈现《海鸥》《向晚》《体面的婚礼》等11部精品剧目。海峡两岸邀约单元集中呈现《小郡之秋》《艺术》等4部优秀作品，展现中国艺术家对国际剧作的精彩…"
