    "content": "新华社北京10月9日电（记者谢希瑶、黄韬铭）商务部新闻发言人9日就美国召集部分经济体发布应对所谓“结构性产能和生产过剩”问题部长级联合声明答记者问时表示，中方反对个别国家以所谓“产能过剩”为名，行贸易保护主义之实，这只会扰乱全球经贸秩序和产供链稳定，给世界经济增长带来长期风险。 有记者问：美东时间10月7日，美贸易代表办公室发布公告称，近期美国召集14个经济体高级官员举行会议，共同签署发布应对所谓“结构性产能和生产过剩”问题的部长级联合声明。请问商务部对此有何评论？ 发言人说，我们注意到有关情况。中方已在不同场合多…"
