    "description": "新华社香港10月9日电 香港特区政府保安局局长邓炳强9日表示，港深双方现已确认皇岗口岸具备安全、畅顺、高效运作和旅客体验良好的开通条件。港深两地将于11日上午在深圳方口岸区举行开通仪式。 香港特区政府保安局和深圳市人民政府口岸办公室9日发出联合公告，宣布皇岗口岸定于12日上午6时30分正式开通运行。 邓炳强说，自皇岗口岸港方口岸区7月31日成立以来，特区政府和各部门已举行逾百次演练，包括两次涉及一万名和两万名公务员的压力测试，并即时优化…",
    "content": "新华社香港10月9日电 香港特区政府保安局局长邓炳强9日表示，港深双方现已确认皇岗口岸具备安全、畅顺、高效运作和旅客体验良好的开通条件。港深两地将于11日上午在深圳方口岸区举行开通仪式。 香港特区政府保安局和深圳市人民政府口岸办公室9日发出联合公告，宣布皇岗口岸定于12日上午6时30分正式开通运行。 邓炳强说，自皇岗口岸港方口岸区7月31日成立以来，特区政府和各部门已举行逾百次演练，包括两次涉及一万名和两万名公务员的压力测试，并即时优化Wi-Fi接收、路面防滑及公共运输交汇处指示等安排。 特区政府入境事务处表示，呼…"
