    "content": "新华社北京10月9日电 题：国家发展改革委有关负责人就《关于发展新质生产力的意见》答记者问 新华社记者 近日，中共中央、国务院印发《关于发展新质生产力的意见》。国家发展改革委有关负责人9日就意见接受采访，回答记者提问。 问：在这个时间点，党中央和国务院印发意见有什么考虑？ 答：党中央和国务院印发意见，主要有3方面考虑。 一是深入贯彻落实习近平总书记重要论述。意见以习近平总书记关于发展新质生产力的重要讲话、重要指示批示、重要论述为根本遵循，总结理论研究成果和生动实践成果，提出19条重大发展改革任务，将习近平总书记的原…"
