    "author": "韩洁,张辛欣,魏玉坤,严赋憬,周圆",
    "description": "新华社北京10月9日电 题：以创新赢未来——习近平经济思想引领中国加快发展新质生产力 新华社记者 10月9日，《中共中央 国务院关于发展新质生产力的意见》公开发布。意见阐明了中国发展新质生产力的总体要求和重点任务，对加强组织实施作出安排。 党的十八大以来，习近平总书记不断深化对生产力发展规律的认识，创造性提出新质生产力这个重要概念和发展新质生产力这个重大任务。习近平总书记关于发展新质生产力的一系列重要论述，创新和发展了马克思主义生产力理…",
    "content": "新华社北京10月9日电 题：以创新赢未来——习近平经济思想引领中国加快发展新质生产力 新华社记者 10月9日，《中共中央 国务院关于发展新质生产力的意见》公开发布。意见阐明了中国发展新质生产力的总体要求和重点任务，对加强组织实施作出安排。 党的十八大以来，习近平总书记不断深化对生产力发展规律的认识，创造性提出新质生产力这个重要概念和发展新质生产力这个重大任务。习近平总书记关于发展新质生产力的一系列重要论述，创新和发展了马克思主义生产力理论，丰富和发展了习近平经济思想，为推动高质量发展和中国式现代化建设提供了科学指引…"
