    "description": "新华社明斯克10月9日电（记者陈汀）白俄罗斯外交部9日发表声明说，白外交部当天召见了乌克兰驻白俄罗斯临时代办诺维茨基，就乌无人机在俄罗斯境内攻击白俄罗斯车牌货车并致白公民重伤一事递交抗议照会。 声明说，乌克兰无人机8日在俄罗斯布良斯克州对一辆悬挂白俄罗斯车牌的货运卡车发动袭击，导致一名白俄罗斯女性公民受重伤。白方此前已警告乌方不得采取此类行动。该车归属显而易见，白方有理由将这次袭击视为“蓄意行为”。 声明说，白方再次警告乌方，类似行为的…",
    "content": "新华社明斯克10月9日电（记者陈汀）白俄罗斯外交部9日发表声明说，白外交部当天召见了乌克兰驻白俄罗斯临时代办诺维茨基，就乌无人机在俄罗斯境内攻击白俄罗斯车牌货车并致白公民重伤一事递交抗议照会。 声明说，乌克兰无人机8日在俄罗斯布良斯克州对一辆悬挂白俄罗斯车牌的货运卡车发动袭击，导致一名白俄罗斯女性公民受重伤。白方此前已警告乌方不得采取此类行动。该车归属显而易见，白方有理由将这次袭击视为“蓄意行为”。 声明说，白方再次警告乌方，类似行为的后果将完全由乌方承担。白方保留采取适当回应措施的权利，并呼吁乌方停止导致局势升级…"
