    "description": "新华社亚的斯亚贝巴10月9日电（记者刘方强）埃塞俄比亚航空公司9日宣布，从11日起恢复从埃塞首都亚的斯亚贝巴飞往该国北部提格雷州首府默克莱的航班。 受当地局势影响，埃塞航空9月23日宣布暂停飞往提格雷地区的默克莱、阿克苏姆和希雷三座城市的航班。 9月23日清晨，当地反政府武装“提格雷人民解放阵线”对阿法尔州和阿姆哈拉州政府军阵地发动“全面进攻”，并接管提格雷地区原先由政府方面控制的机场。近日，埃塞政府军重新夺回对默克莱的控制权，并逐步控…",
    "content": "新华社亚的斯亚贝巴10月9日电（记者刘方强）埃塞俄比亚航空公司9日宣布，从11日起恢复从埃塞首都亚的斯亚贝巴飞往该国北部提格雷州首府默克莱的航班。 受当地局势影响，埃塞航空9月23日宣布暂停飞往提格雷地区的默克莱、阿克苏姆和希雷三座城市的航班。 9月23日清晨，当地反政府武装“提格雷人民解放阵线”对阿法尔州和阿姆哈拉州政府军阵地发动“全面进攻”，并接管提格雷地区原先由政府方面控制的机场。近日，埃塞政府军重新夺回对默克莱的控制权，并逐步控制了提格雷州大部分地区。 埃塞航空暂未宣布何时恢复飞往阿克苏姆和希雷的航班。"
