    "content": "新华社北京10月9日电 题：向“新”向“优”释放假日消费热力 新华社记者潘晔 假期收官，回望今年的中秋国庆双节，家国同庆的温暖图景与流动中国的澎湃动能交织，铺展出一幅热气腾腾的民生画卷。 全社会跨区域人员流动量21.42亿人次，比2025年中秋国庆假期日均水平增长0.6%；增值税发票数据显示，国庆假期全国旅游游览和娱乐服务销售收入同比增长23.6%、餐饮服务销售收入同比增长9%……数据背后，是这个假期持续涌动的消费热力和活力。 长线游、多城串游、奔县游持续升温，赛事旅行、国潮文创、商圈首店、智能场景体验多点开花。消…"
