    "description": "新华社北京10月9日电 综合新华社驻外记者报道：连日来，俄罗斯对乌克兰多地发动导弹和无人机袭击，乌方则远程打击俄大型炼油厂等基础设施，俄最大搜索引擎服务商数据中心遭到无人机袭击。 俄罗斯国防部9日通报说，3日至9日间，俄武装部队对乌克兰发动了1次大规模打击和7次集群打击，打击目标包括乌国防工业企业、后勤和通信中心、军用机场、无人机生产和储存点、燃料和装备仓库及乌军临时部署点等。打击行动造成乌方数个港口设施遭到破坏并停止运行。 俄国防部还…",
    "content": "新华社北京10月9日电 综合新华社驻外记者报道：连日来，俄罗斯对乌克兰多地发动导弹和无人机袭击，乌方则远程打击俄大型炼油厂等基础设施，俄最大搜索引擎服务商数据中心遭到无人机袭击。 俄罗斯国防部9日通报说，3日至9日间，俄武装部队对乌克兰发动了1次大规模打击和7次集群打击，打击目标包括乌国防工业企业、后勤和通信中心、军用机场、无人机生产和储存点、燃料和装备仓库及乌军临时部署点等。打击行动造成乌方数个港口设施遭到破坏并停止运行。 俄国防部还说，过去一周，俄军打击了用于向乌军运送武器装备、燃料和补给物资的14艘干货船和1…"
