    "author": "黄韬铭",
    "description": "新华社北京10月9日电（记者叶昊鸣、李鑫）记者9日从中国大洋事务管理局获悉，搭载“蛟龙”号载人潜水器的“深海一号”船近日从福建厦门起航，赴南太平洋执行中国大洋100航次第二航段科学考察，这也是“蛟龙”号首次在南太平洋开展调查作业。 据了解，本航段将聚焦“数字化深海典型生境”大科学计划目标，通过“蛟龙”号下潜、温盐深测量（CTD）+采水、表层浮游生物拖网等作业手段，首次在南太平洋区域开展水体和海底生态调查，预计时间91天。调查将覆盖该区域…",
    "content": "新华社北京10月9日电（记者叶昊鸣、李鑫）记者9日从中国大洋事务管理局获悉，搭载“蛟龙”号载人潜水器的“深海一号”船近日从福建厦门起航，赴南太平洋执行中国大洋100航次第二航段科学考察，这也是“蛟龙”号首次在南太平洋开展调查作业。 据了解，本航段将聚焦“数字化深海典型生境”大科学计划目标，通过“蛟龙”号下潜、温盐深测量（CTD）+采水、表层浮游生物拖网等作业手段，首次在南太平洋区域开展水体和海底生态调查，预计时间91天。调查将覆盖该区域生境异质性，获取该区域生境分布规律和生态基线数据，填补该区域公海生态数据空白。同…"
