    "content": "新华社香港10月9日电 香港特区立法会9日通过支持香港特区第一个五年规划的议案和2026年施政报告致谢议案，特区行政长官李家超表示感谢。 李家超表示，特区政府制定五年规划，主动对接国家“十五五”规划，引领香港更好把握发展机遇，更好融入和服务国家发展大局，意义重大。他形容五年规划是具前瞻性、策略性和方向性的指导文件，而施政报告是实践五年规划的年度行动方案，两份文件一脉相承，制定过程广泛汇聚各方意见。 他说，今年施政报告主题是“以长远谋全局 以改革开新篇 促发展创机遇 惠民生向未来”，提出各领域的多项政策措施，推进落实…"
