    "description": "新华社南宁10月9日电（记者陆波岸）金秋时节，雨淅淅沥沥下着，葡萄园大棚顶上，雨点敲打声急一阵缓一阵，敲得薄膜噼啪作响。王德利手握剪刀，在大棚里专心修剪葡萄，时不时哼着轻快的曲子，丝毫不受棚外雨声的影响。 “今年的葡萄快卖完了，剩下的果子还得好好管护。”王德利对记者说。 广西桂林市全州县才湾镇毛竹山村村民王德利在管护葡萄。新华社记者 陆波岸 摄 这里是广西桂林市全州县才湾镇毛竹山村，距离红军长征湘江战役纪念馆约10分钟车程。纪念馆所在地…",
    "content": "新华社南宁10月9日电（记者陆波岸）金秋时节，雨淅淅沥沥下着，葡萄园大棚顶上，雨点敲打声急一阵缓一阵，敲得薄膜噼啪作响。王德利手握剪刀，在大棚里专心修剪葡萄，时不时哼着轻快的曲子，丝毫不受棚外雨声的影响。 “今年的葡萄快卖完了，剩下的果子还得好好管护。”王德利对记者说。 广西桂林市全州县才湾镇毛竹山村村民王德利在管护葡萄。新华社记者 陆波岸 摄 这里是广西桂林市全州县才湾镇毛竹山村，距离红军长征湘江战役纪念馆约10分钟车程。纪念馆所在地，是湘江战役脚山铺阻击战的战场遗址。 湘江战役是红军长征的壮烈一战，是决定中国革…"
