    "pub_date": "2026-10-09 21:40:36",
    "author": "舒娜",
    "description": "新华社香港10月9日电（记者舒娜）第二届香港演艺博览9日在香港文化中心开幕。本届博览汇聚来自59个国家及地区的逾1900名业界人士，旨在推动国际表演艺术交流与合作，促进香港表演艺术行业发展，丰富全球表演艺术生态。 本届博览由香港特区政府文化体育及旅游局赞助、香港艺术发展局主办，以“演艺跃动”为主题，于10月9日至13日举行，包括国际精品演出、项目推介、对话交流以及文化体验等。开幕演出为跨界作品《我城》，结合媒体艺术、钢琴与情绪追踪科技，…",
    "content": "新华社香港10月9日电（记者舒娜）第二届香港演艺博览9日在香港文化中心开幕。本届博览汇聚来自59个国家及地区的逾1900名业界人士，旨在推动国际表演艺术交流与合作，促进香港表演艺术行业发展，丰富全球表演艺术生态。 本届博览由香港特区政府文化体育及旅游局赞助、香港艺术发展局主办，以“演艺跃动”为主题，于10月9日至13日举行，包括国际精品演出、项目推介、对话交流以及文化体验等。开幕演出为跨界作品《我城》，结合媒体艺术、钢琴与情绪追踪科技，探索香港这座城市与人的情感脉动。 香港特区政府文化体育及旅游局常任秘书长沈凤君表…"
