    "content": "新华社重庆10月9日电 题：重庆民主村：从更新老社区到运营新生活 新华社记者吴燕霞 刚刚过去的国庆假期，重庆市九龙坡区谢家湾街道民主村社区格外热闹。黄桷树下，老街坊坐在长椅上摆龙门阵；不远处，年轻人端着手冲咖啡拍照打卡，熟悉的社区烟火气与新潮的消费场景交织在一起。 而几年前，这里的景象并非如此。民主村片区曾是原重庆建设厂配套家属区，覆盖民主村、劳动一村、直港大道3个社区，总面积580亩，这里最老的建筑房龄超过70年。随着时间推移，房屋破损、配套老化、道路失修等问题凸显。2021年，九龙坡区被纳入全国首批城市更新试点…"
