    "author": "侯文坤",
    "description": "新华社武汉10月9日电（记者侯文坤）记者从湖北省应急管理厅获悉，湖北省人民政府事故调查组10月9日公布《湖北襄阳宜城市千和百货店“2·18”重大烟花爆竹爆燃事故调查报告》。 2026年2月18日14时22分许，湖北襄阳宜城市郑集镇金铺村四组12号宜城市千和百货店发生一起重大烟花爆竹爆燃事故，造成12人死亡，直接经济损失1279.17万元。 经调查认定，千和百货店“2·18”重大烟花爆竹爆燃事故是一起因顾客在烟花爆竹零售店前违规试放超标烟…",
    "content": "新华社武汉10月9日电（记者侯文坤）记者从湖北省应急管理厅获悉，湖北省人民政府事故调查组10月9日公布《湖北襄阳宜城市千和百货店“2·18”重大烟花爆竹爆燃事故调查报告》。 2026年2月18日14时22分许，湖北襄阳宜城市郑集镇金铺村四组12号宜城市千和百货店发生一起重大烟花爆竹爆燃事故，造成12人死亡，直接经济损失1279.17万元。 经调查认定，千和百货店“2·18”重大烟花爆竹爆燃事故是一起因顾客在烟花爆竹零售店前违规试放超标烟花爆竹（标识为“震天雷”的双响），零售店安全主体责任缺失，违规店外摆放、超核定储…"
