    "author": "熊翔鹤,侯文坤",
    "description": "新华社武汉10月9日电（记者熊翔鹤、侯文坤）詹姆斯·韦布空间望远镜在探索早期宇宙时发现了一类“小红点”星系，它们结构致密、颜色偏红，在宇宙早期大量存在，却在宇宙年龄约20亿年后几乎完全消失，成为天文学界重大疑难问题之一。 华中科技大学物理学院张华年副教授、吴庆文教授团队联合北京大学、中国科学院高能物理研究所等多家机构，基于近100个光谱确认的“小红点”样本展开研究，首次从大尺度环境和暗物质晕质量演化角度揭示其消失之谜。相关研究成果8日在…",
    "content": "新华社武汉10月9日电（记者熊翔鹤、侯文坤）詹姆斯·韦布空间望远镜在探索早期宇宙时发现了一类“小红点”星系，它们结构致密、颜色偏红，在宇宙早期大量存在，却在宇宙年龄约20亿年后几乎完全消失，成为天文学界重大疑难问题之一。 华中科技大学物理学院张华年副教授、吴庆文教授团队联合北京大学、中国科学院高能物理研究所等多家机构，基于近100个光谱确认的“小红点”样本展开研究，首次从大尺度环境和暗物质晕质量演化角度揭示其消失之谜。相关研究成果8日在线发表于国际学术期刊《自然-天文学》。 研究发现，在宇宙极早期，“小红点”更倾向…"
