    "content": "新华社阿什哈巴德10月9日电 独立国家联合体（独联体）成员国领导人9日在土库曼斯坦土库曼巴希签署文件，通过有关独联体成立35周年的声明。声明说，独联体致力于促进成员国间的战略伙伴关系。 文件在当天举行的独联体国家元首理事会会议期间签署。声明说，当今国际关系正经历深刻变革，独联体致力于促进成员国间的战略伙伴关系，并作为一个独特的对话平台，在平等与相互尊重的基础上开展合作。 声明说，在安全方面，独联体成员国开展联合行动的重点领域包括打击国际恐怖主义、跨国犯罪、非法武器和毒品贩运、腐败和洗钱、人口贩运和非法移民，预防和应…"
