    "content": "新华社成都10月9日电 四川省纪委监委9日通报，日前，经四川省委批准，四川省纪委监委对四川省林业和草原局原党组成员、副局长宾军宜严重违纪违法问题进行了立案审查调查。 经查，宾军宜理想信念丧失，纪法意识淡薄，对抗组织审查；违反组织原则，利用职权为他人谋取人事利益；为官不廉，违规收受礼金，违规从事营利活动；私德不修；贪欲膨胀，利用职务上的便利以及职权或者地位形成的便利条件，为他人谋取利益并收受财物，数额特别巨大。 宾军宜严重违反党的政治纪律、组织纪律、廉洁纪律和生活纪律，构成严重职务违法并涉嫌受贿犯罪，且在党的十八大后…"
