    "title": "坦桑尼亚卡车与客车相撞事故导致28人死亡",
    "link": "http://www.news.cn/20261009/71464cdcc9924b889f0acd09e5459529/c.html",
    "pub_date": "2026-10-09 20:33:28",
    "author": "华洪立,林光耀",
    "description": "新华社达累斯萨拉姆10月9日电（记者华洪立 林光耀）坦桑尼亚东部莫罗戈罗省消防救援部门9日说，该省当天凌晨发生一起卡车与客车迎面相撞事故，造成至少28人死亡。 莫罗戈罗省消防救援部门代理指挥官约瑟夫·姆瓦萨贝贾说，一辆载有木材的卡车与一辆从首都达累斯萨拉姆驶往坦桑尼亚南部的客车当天迎面相撞。客车在碰撞后起火并被完全烧毁。 姆瓦萨贝贾说，事故由卡车司机违规超车引发，该司机在未采取充分安全措施的情况下试图超越其他车辆，随后与客车迎面相撞。",
    "content": "新华社达累斯萨拉姆10月9日电（记者华洪立 林光耀）坦桑尼亚东部莫罗戈罗省消防救援部门9日说，该省当天凌晨发生一起卡车与客车迎面相撞事故，造成至少28人死亡。 莫罗戈罗省消防救援部门代理指挥官约瑟夫·姆瓦萨贝贾说，一辆载有木材的卡车与一辆从首都达累斯萨拉姆驶往坦桑尼亚南部的客车当天迎面相撞。客车在碰撞后起火并被完全烧毁。 姆瓦萨贝贾说，事故由卡车司机违规超车引发，该司机在未采取充分安全措施的情况下试图超越其他车辆，随后与客车迎面相撞。"
