    "content": "新华社乌鲁木齐10月9日电（记者高晗）9日，记者从新疆阿勒泰地区教育局获悉，阿勒泰地区义务教育阶段学校2026年“雪假”时间为12月16日（周三）至18日（周五），共3天，与周末（12月19日、20日）相连，形成5天小长假。 阿勒泰地区各县（市）各学校将结合气候条件、本地资源和课程目标，立足2025年试行“雪假”经验，聚焦冰雪运动普及和冰雪文化启蒙，开展多样化冰雪实践活动。 今年“雪假”期间，阿勒泰地区将持续开展冰雪系列主题活动，联动四大滑雪度假区、人类滑雪起源地博物馆等资源，组织学生开展冰雪研学、冰雪竞技、冰雪民…"
