    "content": "河南省信阳市罗山县何家冲村，是红二十五军长征出发地。 1934年，红二十五军在何家冲村的一棵古银杏树下集结。他们转战近万里，率先到达陕北，被誉为“北上先锋”。 1934年11月，红二十五军到达罗山县何家冲进行人员和装备上的整顿。16日夜里，将士们在何家冲的古银杏树下，高举“中国工农红军北上抗日第二先遣队”的旗帜，开始了英勇的征程。 何桂英是罗山县何家冲村人，是“英雄母亲”何大妈的曾外孙女，也是村里的义务讲解员。何桂英说，红军出发时，老百姓送上了鸡蛋，还有连夜缝制的布鞋，依依不舍地送别红军。 “红军集结时搭了棚，不到…"
