    "author": "魏梦佳",
    "description": "新华社北京10月9日电（记者魏梦佳）记者从北京大学获悉，哲学史家、北京大学哲学系（宗教学系）教授楼宇烈先生于2026年10月9日在北京因病逝世，享年92岁。 楼宇烈1934年生于杭州。1960年他在北京大学哲学系本科毕业后留校任教，长期从事中国哲学史、佛教哲学、东方哲学和宗教学等方面的教学研究工作。 多年来，楼宇烈倾心培育人才，恪守学者品格，笔耕不辍，从魏晋玄学入手，贯通儒释道，倡导东方哲学，主张创建符合中国文化特点的宗教学理论。其代表…",
    "content": "新华社北京10月9日电（记者魏梦佳）记者从北京大学获悉，哲学史家、北京大学哲学系（宗教学系）教授楼宇烈先生于2026年10月9日在北京因病逝世，享年92岁。 楼宇烈1934年生于杭州。1960年他在北京大学哲学系本科毕业后留校任教，长期从事中国哲学史、佛教哲学、东方哲学和宗教学等方面的教学研究工作。 多年来，楼宇烈倾心培育人才，恪守学者品格，笔耕不辍，从魏晋玄学入手，贯通儒释道，倡导东方哲学，主张创建符合中国文化特点的宗教学理论。其代表作《王弼集校释》是当代中国学术经典，《中国的品格》《中国文化的根本精神》等是国际…"
